const tabId = 1962625065;
const data = await browserjs(tabId, () => {
  const textNodes = [];
  const walk = (node) => {
    if (node.nodeType === Node.TEXT_NODE) {
      if (node.textContent.trim()) textNodes.push(node.textContent.trim());
    } else {
      for (const child of node.childNodes) walk(child);
    }
  };

  // Find element containing "Today's Conditions" or "Wind"
  const windElem = Array.from(document.querySelectorAll('*')).find(el => el.textContent && el.textContent.includes('Wind') && el.textContent.includes('km/h'));

  return {
    url: window.location.href,
    title: document.title,
    windElemSnippet: windElem ? windElem.innerText : null
  };
});

console.log(JSON.stringify(data, null, 2));

